{"title":"Moon","rest":{"pages":3}}; null

after:
```javascript
function summarizeNote(note) {
  const {name: title = "Untitled", ...rest} = note;
  return {title, rest};
}
console.log(JSON.stringify(summarizeNote({name: "Moon", pages: 3})));
console.log(summarizeNote({name: null}).title);
```
